#!/usr/bin/env python3
"""Generate rtl/sine_lut.sv: a 256-entry signed 16-bit sine ROM (full scale)."""
import math
from pathlib import Path

lines = [
    "// Generated by scripts/gen_sine_lut.py -- do not edit.",
    "// 256-entry signed 16-bit sine, one full period.",
    "module sine_lut (",
    "    input  logic [7:0]        addr,",
    "    output logic signed [15:0] data",
    ");",
    "  always_comb begin",
    "    case (addr)",
]
for i in range(256):
    v = round(32767 * math.sin(2 * math.pi * i / 256))
    lines.append(f"      8'd{i}: data = 16'sd{v};" if v >= 0 else f"      8'd{i}: data = -16'sd{-v};")
lines += ["      default: data = 16'sd0;", "    endcase", "  end", "endmodule", ""]
Path(__file__).resolve().parent.parent.joinpath("rtl", "sine_lut.sv").write_text("\n".join(lines))
